fn putmask(a: Vec<f32>, mask: Vec<bool>, values: Vec<f32>) -> Vec<f32> {
    // The mask must be the same length as `a`, and `values` must be non-empty.
    assert_eq!(
        a.len(),
        mask.len(),
        "mask and input arrays must have the same length"
    );
    assert!(
        !values.is_empty(),
        "replacement values array must be non-empty"
    );

    let v_len = values.len();
    let mut result = Vec::with_capacity(a.len());

    for (i, (aval, m)) in a.into_iter().zip(mask.into_iter()).enumerate() {
        if m {
            // pick from `values`, wrapping around via modulo
            result.push(values[i % v_len]);
        } else {
            // keep the original input value
            result.push(aval);
        }
    }

    result
}